<script>
    // Safely get value from potential array or direct value
    function SafeGetValue(value, defaultValue = "--") {
        if (value === undefined || value === null) return defaultValue;
        if (Array.isArray(value) && value.length > 0) return String(value[0]);
        return String(value);
    }

    // --- NEW --- Helper function specifically for option text display
    function GetOptionDisplayText(value, defaultValue = "--") {
        let rawValue = "--";
        if (value !== undefined && value !== null) {
            // Get the base value (first element if array, otherwise the value itself)
            if (Array.isArray(value) && value.length > 0) {
                rawValue = String(value[0]);
            } else {
                rawValue = String(value);
            }
        } else {
            rawValue = defaultValue;
        }

        // Check for the update arrow '->'
        const arrowIndex = rawValue.indexOf('->');
        if (arrowIndex !== -1) {
            // Return only the part *after* the arrow
            return rawValue.substring(arrowIndex + 2).trim();
        } else {
            // No arrow, return the original value
            return rawValue;
        }
    }


    // Update progress bar and text value
    function updateProgressBar(barId, valueId, value, min = 0, max = 100, color) {
        const progressBar = document.getElementById(barId);
        const valueDisplay = document.getElementById(valueId);
        if (!progressBar || !valueDisplay) return;

        let displayValue = SafeGetValue(value, String(min));
        let numericValue = min;

        const matches = String(displayValue).match(/-?\d+(\.\d+)?/g);
        if (matches && matches.length > 0) {
            numericValue = parseFloat(matches[matches.length - 1]);
        } else if (!isNaN(parseFloat(displayValue))) {
            numericValue = parseFloat(displayValue);
        }

        valueDisplay.innerText = displayValue;

        numericValue = Math.max(min, Math.min(max, numericValue));
        const range = max - min;
        const percentage = range === 0 ? 0 : ((numericValue - min) / range) * 100;

        progressBar.style.width = `${percentage}%`;
        if (color) {
            progressBar.style.backgroundColor = color;
        }
    }

    // Switch active tab
    function switchTab(tabName) {
        const buttons = document.querySelectorAll('.tab-button');
        const panels = document.querySelectorAll('.character-panel');

        buttons.forEach(button => button.classList.remove('active'));
        panels.forEach(panel => panel.classList.remove('active'));

        document.getElementById(`tab-${tabName}`).classList.add('active');
        document.getElementById(`panel-${tabName}`).classList.add('active');
    }

    // Initialize the display
    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                console.error("Status UI: No message data found.");
                return;
            }

            const data = messages[0].data.display_data || messages[0].data.stat_data;

            if (!data) {
                console.error("Status UI: Both display_data and stat_data are missing.");
                return;
            }

            // --- Populate Room Info ---
            if (data.房间) {
                document.getElementById('room-stage').innerText = SafeGetValue(data.房间.阶段, '1');
                document.getElementById('option-intensity-overall').innerText = SafeGetValue(data.房间.选项强度等级, '1');
                // --- MODIFIED --- Use GetOptionDisplayText for options
                document.getElementById('option-a').innerText = `A: ${GetOptionDisplayText(data.房间.当前每日选项A, '--')}`;
                document.getElementById('option-b').innerText = `B: ${GetOptionDisplayText(data.房间.当前每日选项B, '--')}`;
                document.getElementById('option-c').innerText = `C: ${GetOptionDisplayText(data.房间.当前每日选项C, '--')}`;
            }

            // --- Populate Yuehua's Panel ---
            if (data.月华) {
                updateProgressBar('yuehua-aff-xingyao-bar', 'yuehua-aff-xingyao', data.月华.对星瑶好感度, 0, 100, 'var(--progress-yuehua)');
                updateProgressBar('yuehua-aff-user-bar', 'yuehua-aff-user', data.月华.对用户好感度, -100, 100, 'var(--accent-soft-blue)');
                updateProgressBar('yuehua-guilt-xingyao-bar', 'yuehua-guilt-xingyao', data.月华.对星瑶负罪感, 0, 100, '#fdd835');
                updateProgressBar('yuehua-guilt-user-bar', 'yuehua-guilt-user', data.月华.对用户负罪感, 0, 100, '#fdd835');
                updateProgressBar('yuehua-obedience-bar', 'yuehua-obedience', data.月华.服从度, 0, 100, '#b0bec5');
                updateProgressBar('yuehua-mental-bar', 'yuehua-mental', data.月华.精神状态, 0, 100, 'var(--progress-yuehua)');
            }

             // --- Populate Xingyao's Panel ---
            if (data.星瑶) {
                updateProgressBar('xingyao-aff-yuehua-bar', 'xingyao-aff-yuehua', data.星瑶.对月华好感度, 0, 100, 'var(--progress-xingyao)');
                updateProgressBar('xingyao-aff-user-bar', 'xingyao-aff-user', data.星瑶.对用户好感度, -100, 100, 'var(--accent-soft-blue)');
                updateProgressBar('xingyao-guilt-yuehua-bar', 'xingyao-guilt-yuehua', data.星瑶.对月华负罪感, 0, 100, '#fdd835');
                updateProgressBar('xingyao-guilt-user-bar', 'xingyao-guilt-user', data.星瑶.对用户负罪感, 0, 100, '#fdd835');
                updateProgressBar('xingyao-obedience-bar', 'xingyao-obedience', data.星瑶.服从度, 0, 100, '#b0bec5');
                updateProgressBar('xingyao-mental-bar', 'xingyao-mental', data.星瑶.精神状态, 0, 100, 'var(--progress-xingyao)');
            }

             switchTab('yuehua'); // Default to Yuehua's tab

        } catch (error) {
            console.error("Error initializing status display:", error);
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);

</script>
</body>
</html>
